"""星驰 API Key 用量查询；命令 ,api。凭据仅保存在 data/xingchi-api.json。"""
import asyncio
import base64
import html
import http.client
import io
import json
import math
import re
import ssl
import time
from datetime import datetime,timedelta,timezone
from decimal import Decimal,InvalidOperation
from pathlib import Path
from urllib.error import HTTPError,URLError
from urllib.request import Request,build_opener,HTTPRedirectHandler
from pagermaid.listener import listener
from pagermaid.static import working_dir
from pyrogram.enums import ParseMode

CONFIG_PATH=Path(working_dir)/'data'/'xingchi-api.json'
BASE='https://api.xingchiapi.com'
TZ=timezone(timedelta(hours=8))
RUNNING=False

class UsageError(Exception):pass
class NoRedirect(HTTPRedirectHandler):
    def redirect_request(self,*args):return None

def load_key():
    try:
        data=json.loads(CONFIG_PATH.read_text())
        key=data.get('api_key')
        if not isinstance(key,str) or not re.fullmatch(r'sk-[A-Za-z0-9_-]{16,256}',key):raise ValueError()
        return key
    except (OSError,ValueError,TypeError):
        raise UsageError('请在本机 data/xingchi-api.json 配置有效 API Key。') from None

def integer(value):
    if type(value) is not int or value<0:raise UsageError('接口用量数据不完整，未生成图片。')
    return value

def amount(value):
    if value is None:return None
    try:
        n=Decimal(str(value))
        if not n.is_finite() or n<0:raise ValueError()
        return n
    except (ValueError,InvalidOperation):raise UsageError('接口金额格式异常。') from None

def decode_usage(overview,now=None):
    if not isinstance(overview,dict) or overview.get('isValid') is not True:
        raise UsageError('API Key 无效、已停用或接口未确认有效。')
    usage=overview.get('usage')
    if not isinstance(usage,dict):raise UsageError('接口没有返回用量统计。')
    today=usage.get('today');total=usage.get('total')
    if not isinstance(today,dict) or not isinstance(total,dict):raise UsageError('今日或累计统计缺失。')
    days=overview.get('daily_usage')
    if not isinstance(days,list):raise UsageError('每日用量记录缺失。')
    indexed={}
    for row in days:
        if not isinstance(row,dict):raise UsageError('每日用量格式异常。')
        try:day=datetime.strptime(row['date'],'%Y-%m-%d').date()
        except (ValueError,TypeError,KeyError):raise UsageError('每日用量日期异常。') from None
        if day in indexed:raise UsageError('每日用量日期重复。')
        indexed[day]=integer(row.get('total_tokens'))
    now=(now or datetime.now(TZ)).astimezone(TZ)
    points=[]
    for offset in range(6,-1,-1):
        day=now.date()-timedelta(days=offset)
        points.append((day.strftime('%m-%d'),indexed.get(day)))
    unit=overview.get('unit')
    if unit!='USD':raise UsageError('接口金额单位不是预期的 USD，请核实。')
    return {'today_tokens':integer(today.get('total_tokens')),'today_requests':integer(today.get('requests')),
            'total_tokens':integer(total.get('total_tokens')),'total_requests':integer(total.get('requests')),
            'cost':amount(total.get('actual_cost')),'balance':amount(overview.get('remaining',overview.get('balance'))),
            'points':points}

def fetch_usage():
    key=load_key();opener=build_opener(NoRedirect())
    url=BASE+'/v1/usage?days=7&timezone=Asia%2FShanghai'
    for attempt in range(3):
        retry=False
        try:
            req=Request(url,headers={'Authorization':'Bearer '+key,'Accept':'application/json','User-Agent':'PagerMaid-Xingchi-Usage/1.0','Connection':'close'})
            with opener.open(req,timeout=15) as response:
                if response.status!=200:raise UsageError('接口未返回完整响应。')
                raw=response.read(2*1024*1024+1)
            if len(raw)>2*1024*1024:raise UsageError('接口响应过大。')
            return decode_usage(json.loads(raw))
        except HTTPError as exc:
            status=exc.code;exc.close()
            if status in (401,403):raise UsageError('Key 无效、已过期或无查询权限。') from None
            if status==429:raise UsageError('查询频率受限，请稍后再试。') from None
            if status not in (408,500,502,503,504):raise UsageError('接口 HTTP '+str(status)) from None
            retry=True
        except ssl.SSLError:raise UsageError('证书校验失败，已停止请求。') from None
        except (URLError,ConnectionError,TimeoutError,OSError,http.client.HTTPException):retry=True
        except (ValueError,UnicodeError):raise UsageError('接口返回格式异常，未生成图片。') from None
        if retry and attempt<2:time.sleep(0.8*(attempt+1))
    raise UsageError('连接失败，已尝试3次，请稍后重试。')

def build_usage_caption(data):
    cost='暂无' if data['cost'] is None else f"{data['cost']:,.2f} USD"
    balance='暂无' if data['balance'] is None else f"{data['balance']:,.2f} USD"
    lines=[f"今日用量：<code>{compact_tokens(data['today_tokens'])} Tokens</code>",
           f"累计用量：<code>{compact_tokens(data['total_tokens'])} Tokens</code>",
           f"累计消费：<code>{cost}</code>",f"剩余额度：<code>{balance}</code>"]
    return '<b>OpenAI API 用量</b>\n\n<blockquote>'+'\n\n'.join(lines)+'</blockquote>'

@listener(command='api',outgoing=True,ignore_edited=True,description='星驰指定 Key 的用量与余额')
async def api_usage(client,message):
    global RUNNING
    options={'parse_mode':ParseMode.HTML}
    thread=getattr(message,'message_thread_id',None)
    if thread is not None:options['message_thread_id']=thread
    try:await message.delete()
    except Exception:
        await client.send_message(message.chat.id,'无法删除指令消息，请检查权限。',**options);return
    if RUNNING:
        await client.send_message(message.chat.id,'当前查询尚未完成，请稍候。',**options);return
    RUNNING=True;image=None
    try:
        data=await asyncio.to_thread(fetch_usage)
        image=await asyncio.to_thread(create_usage_card,data)
        await client.send_photo(message.chat.id,image,caption=build_usage_caption(data),**options)
    except Exception as exc:
        detail=str(exc) if isinstance(exc,UsageError) else type(exc).__name__
        await client.send_message(message.chat.id,'用量查询失败：'+html.escape(detail),**options)
    finally:
        if image is not None:image.close()
        RUNNING=False

def compact_tokens(value):
    for unit, threshold in (("兆", 10**12), ("亿", 10**8), ("万", 10**4)):
        if value >= threshold:
            return f"{value / threshold:.2f}{unit}"
    return f"{value:,}"


