_DSYL_FONT_REGULAR_B64 = ""
_DSYL_FONT_BOLD_B64 = ""
_DSYL_FONT_LATIN_B64 = ""
_DSYL_FONT_LATIN_REGULAR_B64 = ""

def create_usage_card(data):
    from PIL import Image, ImageDraw, ImageFilter, ImageFont
    width, height = 1200, 820
    class SmoothDraw:
        """Antialias local geometry in bounded tiles; leave text on its native pixel grid."""
        def __init__(self, target):
            self.target = target
            self.native = ImageDraw.Draw(target)

        def __getattr__(self, name):
            return getattr(self.native, name)

        def geometry(self, kind, xy, **kwargs):
            scale = 4
            pad = max(4, math.ceil(kwargs.get('width', 1) / 2) + 3)
            points = list(xy)
            if points and isinstance(points[0], (tuple, list)):
                points = [coordinate for pair in points for coordinate in pair]
            xs, ys = points[::2], points[1::2]
            left = max(0, math.floor(min(xs)) - pad)
            top = max(0, math.floor(min(ys)) - pad)
            right = min(self.target.width, math.ceil(max(xs)) + pad + 1)
            bottom = min(self.target.height, math.ceil(max(ys)) + pad + 1)
            if right <= left or bottom <= top:
                return
            for y in range(top, bottom, 128):
                y_end = min(y + 128, bottom)
                for x in range(left, right, 128):
                    x_end = min(x + 128, right)
                    # Opaque, flat card interiors need no supersampling or temporary image.
                    inset = kwargs.get('radius', 0) + kwargs.get('width', 1) + pad
                    if (kind == 'rounded_rectangle' and kwargs.get('fill') is not None
                            and x >= min(xs) + inset and x_end - 1 <= max(xs) - inset
                            and y >= min(ys) + inset and y_end - 1 <= max(ys) - inset):
                        self.native.rectangle((x, y, x_end - 1, y_end - 1), fill=kwargs['fill'])
                        continue
                    render_left, render_top = max(0, x-pad), max(0, y-pad)
                    render_right = min(self.target.width, x_end+pad)
                    render_bottom = min(self.target.height, y_end+pad)
                    coords = [round((value - (render_left if i % 2 == 0 else render_top)) * scale)
                              for i, value in enumerate(points)]
                    if kind in ('line', 'polygon'):
                        coords = list(zip(coords[::2], coords[1::2]))
                    options = dict(kwargs)
                    for key in ('radius', 'width'):
                        if key in options:
                            options[key] *= scale
                    with Image.new('RGBA', ((render_right-render_left)*scale,
                                           (render_bottom-render_top)*scale)) as layer:
                        getattr(ImageDraw.Draw(layer), kind)(coords, **options)
                        with layer.resize((render_right-render_left, render_bottom-render_top),
                                          Image.Resampling.BOX) as smooth:
                            with smooth.crop((x-render_left, y-render_top,
                                              x_end-render_left, y_end-render_top)) as tile:
                                self.target.alpha_composite(tile, (x, y))

        def rounded_rectangle(self, xy, **kwargs):
            self.geometry('rounded_rectangle', xy, **kwargs)

        def ellipse(self, xy, **kwargs):
            self.geometry('ellipse', xy, **kwargs)

        def polygon(self, xy, **kwargs):
            self.geometry('polygon', xy, **kwargs)

        def line(self, xy, **kwargs):
            self.geometry('line', xy, **kwargs)

    image = Image.new("RGBA", (width, height), "#05070d")
    ambient = Image.new("RGBA", image.size)
    draw = ImageDraw.Draw(ambient)
    draw.ellipse((760, -260, 1400, 330), fill=(36, 211, 238, 40))
    draw.ellipse((-220, height - 260, 360, height + 200), fill=(139, 92, 246, 30))
    with ambient.filter(ImageFilter.GaussianBlur(120)) as blurred:
        composed = Image.alpha_composite(image, blurred)
    ambient.close()
    image.close()
    image = composed
    draw = SmoothDraw(image)
    font_data = dict(regular=_DSYL_FONT_REGULAR_B64, bold=_DSYL_FONT_BOLD_B64,
                     latin=_DSYL_FONT_LATIN_B64, latin_regular=_DSYL_FONT_LATIN_REGULAR_B64)
    fonts, decoded_fonts = {}, {}

    def get_font(kind, size):
        key = kind, size
        if key not in fonts:
            if kind not in decoded_fonts:
                decoded_fonts[kind] = base64.b64decode(font_data[kind])
            fonts[key] = ImageFont.truetype(io.BytesIO(decoded_fonts[kind]), size)
        return fonts[key]

    def runs(value, size, bold):
        for part in re.findall(r"[\x00-\x7f]+|[^\x00-\x7f]+", value):
            kind = ("latin" if bold else "latin_regular") if part.isascii() else ("bold" if bold else "regular")
            yield part, get_font(kind, size)

    def measure(value, size, bold=True):
        return sum(draw.textlength(part, font=font) for part, font in runs(value, size, bold))

    def text(x, baseline, value, size=28, color="#f8fafc", bold=True, right=False):
        if right:
            x -= measure(value, size, bold)
        for part, font in runs(value, size, bold):
            draw.native.text((round(x), round(baseline)), part, font=font, fill=color, anchor="ls")
            x += draw.textlength(part, font=font)

    def fit_size(value, maximum_width, preferred, bold=True):
        for size in range(preferred, 10, -1):
            if measure(value, size, bold) <= maximum_width:
                return size
        return 10

    text(55, 82, "OpenAI", 50)
    text(55 + measure("OpenAI", 50) + 16, 82, "API 用量", 50, "#38d6ee")
    cost = data.get("cost")
    amount = "暂无" if cost is None else f"{cost:,.2f}"
    if cost is not None and len(amount) > 25:
        amount = f"{cost:.6g}"
    for left, label, value, count, accent in (
        (44, "今日用量", compact_tokens(data["today_tokens"]), data["today_requests"], "#38d6ee"),
        (422, "累计用量", compact_tokens(data["total_tokens"]), data["total_requests"], "#a78bfa"),
        (800, "累计金额", amount, None, "#e4c48b"),
    ):
        right = left + 356
        x = left + 30
        draw.rounded_rectangle((left, 124, right, 352), radius=26, fill="#090d15", outline="#1b2636", width=2)
        text(x, 181, label, 32)
        value_x = x
        if count is None and cost is not None:
            text(x, 263, "$", 40)
            value_x += round(measure("$", 40)) + 8
        text(value_x, 263, value, fit_size(value, right - 30 - value_x, 64))
        draw.rounded_rectangle((x, 289, x + 30, 295), radius=3, fill=accent)
        footer_x = x + 44
        if count is None:
            if cost is not None:
                text(footer_x, 311, "USD", 24, "#c1cad8", bold=False)
                text(footer_x + 65, 311, "Key", 24, "#c1cad8")
        else:
            requests = f"{count:,} 次请求"
            unit_x = right - 30
            available = unit_x - measure("Tokens", 24, False) - footer_x - 12
            text(footer_x, 311, requests, fit_size(requests, available, 26, False), "#c1cad8", bold=False)
            text(unit_x, 311, "Tokens", 24, "#9ba9bd", bold=False, right=True)
    draw.rounded_rectangle((44, 380, 1156, 776), radius=26, fill="#090d15", outline="#1b2636", width=2)
    text(78, 435, "近 7 天用量", 32)
    text(1122, 432, "北京时间", 24, "#9ba9bd", bold=False, right=True)
    ceiling = max(2, max((value for _, value in data["points"] if value is not None), default=0))
    axis_width = max(measure(compact_tokens(round(ceiling * fraction)), 24, False) for fraction in (0, .5, 1))
    x0, x1, top, bottom = max(180, 78 + axis_width + 24), 1096, 491, 687
    for fraction in (0, .5, 1):
        y = bottom - fraction * (bottom - top)
        draw.native.line((x0, round(y), x1, round(y)), fill="#1b2636", width=1)
        text(x0 - 24, y + 8, compact_tokens(round(ceiling * fraction)), 24, "#9ba9bd", bold=False, right=True)
    points = [None if value is None else (x0 + i * (x1 - x0) / 6, bottom - value / ceiling * (bottom - top)) for i, (_, value) in enumerate(data["points"])]
    segments, segment = [], []
    for point in points + [None]:
        if point is None:
            if segment:
                segments.append(segment)
                segment = []
        else:
            segment.append(point)
    for segment in segments:
        if len(segment) > 1:
            polygon = [(segment[0][0], bottom), *segment, (segment[-1][0], bottom)]
            draw.polygon(polygon, fill=(56, 214, 238, 15))
    for segment in segments:
        if len(segment) > 1:
            draw.line(segment, fill="#38d6ee", width=5, joint="curve")
    for i, point in enumerate(points):
        x = x0 + i * (x1 - x0) / 6
        if point is not None:
            _, y = point
            draw.ellipse((x - 5, y - 5, x + 5, y + 5), fill="#38d6ee")
        label = data["points"][i][0]
        text(x - measure(label, 24, False) / 2, 738, label, 24, "#c1cad8", bold=False)
    if points[-1] is not None:
        draw.ellipse((points[-1][0] - 9, points[-1][1] - 9, points[-1][0] + 9, points[-1][1] + 9), fill="#38d6ee")
    result = io.BytesIO()
    with image.convert("RGB") as rgb:
        rgb.save(result, "PNG", optimize=True)
    image.close()
    result.name = "openai-api-usage.png"
    result.seek(0)
    return result

